function y(t,n,c=.75){let u=c+Math.max(0,n)**2/19.6;return Math.min(240,450/Math.max(.1,t),192/u)}function x(t,n,c,u,o){let r=t*n*9.8,i=c*u*9.8;return{weight:r,buoyancy:i,support:o?Math.max(0,r-i):0}}function M(t,n){return{x:n,y:-t}}function f(t,n=.1){if(!t.length)return[];let c=[],u=t[t.length-1].t,o=1;for(let r=0;r*n<=u+1e-10;r++){let i=r*n;for(;o<t.length-1&&t[o].t<i;)o++;let e=t[Math.max(0,o-1)],h=t[Math.min(o,t.length-1)],a=h.t>e.t?Math.max(0,Math.min(1,(i-e.t)/(h.t-e.t))):0;c.push({t:i,y0:e.y0+(h.y0-e.y0)*a,y1:e.y1+(h.y1-e.y1)*a})}return c}export{y as a,x as b,M as c,f as d};
